package org.com.sharekhan.analysis;
import org.junit.jupiter.api.Test;import org.com.sharekhan.service.SharekhanHistoricalService.HistoricalCandle;
import java.time.*;import java.util.*;import java.math.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class WeeklyTechnicalTest {
 final SwingSessions calendar=new SwingSessions();final LocalDate day=LocalDate.of(2026,10,30);
 WeeklyTechnicalService service(SavedDailyAnalysis d){return new WeeklyTechnicalService(d,calendar,Clock.fixed(Instant.parse("2026-11-01T20:00:00Z"),StockAnalysisService.IST));}
 List<HistoricalCandle> bars(LocalDate through,int count){var rows=new ArrayList<HistoricalCandle>();for(var d=through;rows.size()<count;d=d.minusDays(1))if(calendar.regular(d)||d.equals(LocalDate.of(2026,2,1))||!calendar.supported(d)&&d.getDayOfWeek().getValue()<6)rows.add(new HistoricalCandle(d,LocalTime.MIDNIGHT,100,101,99,100,1_000_000L));Collections.reverse(rows);for(int i=0;i<rows.size();i++){var b=rows.get(i);double c=100+i*.1;rows.set(i,new HistoricalCandle(b.date(),b.time(),c-.1,c+.5,c-.5,c,(i+1)*100_000L));}return rows;}
 StockDailyHistoryStore.Saved saved(List<HistoricalCandle> rows){return new StockDailyHistoryStore.Saved("DEMO","10",new BigDecimal(".05"),Instant.now(),rows);}
 WeeklyTechnicalService.Report eval(List<HistoricalCandle> rows,LocalDate cutoff){return service(mock(SavedDailyAnalysis.class)).evaluate(saved(rows),cutoff);}
 @Test void daily200IsExactlyDailyClosesAndNeverAWeeklySubstitute(){var rows=bars(day,420);var r=eval(rows,day);assertThat(r.status()).isEqualTo("AVAILABLE");assertThat(r.weeklyThrough()).isEqualTo(day);double expected=rows.subList(rows.size()-200,rows.size()).stream().mapToDouble(HistoricalCandle::close).average().orElseThrow();assertThat(r.sma200Day()).isCloseTo(expected,within(.0000001));assertThat(r.sma20Week()).isCloseTo(r.weeks().subList(r.weeks().size()-20,r.weeks().size()).stream().mapToDouble(WeeklyTechnicalService.Week::close).average().orElseThrow(),within(.0000001));assertThat(r.sma200Day()).isNotEqualTo(r.sma50Week());assertThat(r.rules()).anyMatch(s->s.contains("200-DAY")&&s.contains("not equivalent"));}
 @Test void aggregationHonorsHolidayWeekAndBudgetsSunday(){var rows=bars(day,420);var r=eval(rows,day);var holiday=r.weeks().stream().filter(w->w.weekStart().equals(LocalDate.of(2026,10,19))).findFirst().orElseThrow();assertThat(holiday.sessions()).isEqualTo(4);var source=rows.stream().filter(b->!b.date().isBefore(holiday.weekStart())&&b.date().isBefore(holiday.weekStart().plusDays(7))).toList();assertThat(holiday.volume()).isEqualTo(source.stream().mapToLong(HistoricalCandle::volume).sum());assertThat(holiday.open()).isEqualTo(source.getFirst().open());assertThat(holiday.close()).isEqualTo(source.getLast().close());var budget=r.weeks().stream().filter(w->w.weekStart().equals(LocalDate.of(2026,1,26))).findFirst().orElseThrow();assertThat(budget.lastSession()).isEqualTo(LocalDate.of(2026,2,1));assertThat(budget.sessions()).isEqualTo(5);}
 @Test void unfinishedWeekIsExcludedAndAllAveragesShareWeeklyCutoff(){var wed=LocalDate.of(2026,11,4);var rows=bars(wed,420);var r=eval(rows,wed);assertThat(r.dataDate()).isEqualTo(wed);assertThat(r.weeklyThrough()).isEqualTo(day);var filtered=rows.stream().filter(b->!b.date().isAfter(day)).toList();assertThat(r.sma200Day()).isCloseTo(filtered.subList(filtered.size()-200,filtered.size()).stream().mapToDouble(HistoricalCandle::close).average().orElseThrow(),within(.000001));assertThat(r.weeks()).noneMatch(w->w.weekStart().equals(LocalDate.of(2026,11,2)));}
 @Test void missingOlderVerifiedWeekBreaksAveragesInsteadOfCompressingTime(){var rows=bars(day,420);rows.removeIf(b->b.date().equals(LocalDate.of(2026,6,17)));var r=eval(rows,day);assertThat(r.status()).isEqualTo("LIMITED_HISTORY");assertThat(r.sma50Week()).isNull();assertThat(r.weeks()).noneMatch(w->w.weekStart().equals(LocalDate.of(2026,6,15)));assertThat(r.evidence()).anyMatch(s->s.contains("partial/incomplete"));}
 @Test void shortListingKeepsChartButUnavailableAveragesAreNull(){var r=eval(bars(day,96),day);assertThat(r.status()).isEqualTo("LIMITED_HISTORY");assertThat(r.sma50Week()).isNull();assertThat(r.sma200Day()).isNull();assertThat(r.weeks()).isNotEmpty();assertThat(r.rules()).anyMatch(s->s.contains("not calibrated probabilities"));}
 @Test void futureCandlesCannotAlterHistoricalChartOrConfirmedLevels(){var rows=bars(day,420);var before=eval(rows,day);rows.add(new HistoricalCandle(day.plusDays(5),LocalTime.MIDNIGHT,1,10000,1,9999,99_000_000L));var after=eval(rows,day);assertThat(after.weeks()).isEqualTo(before.weeks());assertThat(after.pivots()).isEqualTo(before.pivots());assertThat(after.sma200Day()).isEqualTo(before.sma200Day());}
 @Test void invalidStaleMissingAndDiscontinuousInputsFailClosed(){var rows=bars(day,420);assertThat(eval(rows.subList(0,419),day).status()).isEqualTo("UNAVAILABLE");rows=bars(day,420);rows.removeIf(b->b.date().equals(LocalDate.of(2026,10,28)));assertThat(eval(rows,day).reason()).contains("Missing recent");rows=bars(day,420);var b=rows.get(50);rows.set(50,new HistoricalCandle(b.date(),b.time(),200,201,199,200,1_000_000L));assertThat(eval(rows,day).reason()).contains("corporate-action");rows=bars(day,420);rows.add(new HistoricalCandle(day,LocalTime.MIDNIGHT,150,152,149,151,1L));assertThat(eval(rows,day).reason()).contains("conflicting");}
 @Test void zonesCountDistinctWeeksAndExposeWeakEvidence(){var start=LocalDate.of(2026,1,5);var p=List.of(new WeeklyTechnicalService.Pivot("LOW",start,100),new WeeklyTechnicalService.Pivot("HIGH",start,100.5),new WeeklyTechnicalService.Pivot("LOW",start.plusWeeks(3),100.7),new WeeklyTechnicalService.Pivot("HIGH",start.plusWeeks(5),150));var zones=WeeklyTechnicalService.zones(p,120);assertThat(zones).hasSize(2);assertThat(zones.getFirst().role()).isEqualTo("SUPPORT");assertThat(zones.getFirst().touches()).isEqualTo(2);assertThat(zones.getLast().touches()).isEqualTo(1);assertThat(zones.getLast().role()).isEqualTo("RESISTANCE");}
 @Test void perSessionVolumeComparisonDoesNotMistakeHolidayLengthForFlow(){var rows=bars(day,420);for(int i=0;i<rows.size();i++){var b=rows.get(i);rows.set(i,new HistoricalCandle(b.date(),b.time(),b.open(),b.high(),b.low(),b.close(),1_000_000L));}assertThat(eval(rows,day).volumePerSessionRatio()).isEqualTo(1);}
 @Test void symbolWhitelistAndMinuteCacheUseOnlySavedInputs(){var d=mock(SavedDailyAnalysis.class);when(d.members()).thenReturn(List.of(new StockDailyHistoryStore.Member("DEMO","INE1",day)));when(d.read("DEMO",day)).thenReturn(saved(bars(day,420)));var s=service(d);var a=s.report(" demo ");assertThat(s.report("DEMO")).isSameAs(a);verify(d,times(1)).read("DEMO",day);assertThatThrownBy(()->s.report("../../etc/passwd")).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);assertThatThrownBy(()->s.report("UNKNOWN")).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);}
 @Test void confirmedRisingAndFallingSwingsRequireAlignedAverages(){for(boolean up:new boolean[]{true,false}){var rows=bars(day,420);var start=WeeklyTechnicalService.monday(rows.getFirst().date());for(int i=0;i<rows.size();i++){var b=rows.get(i);long week=java.time.temporal.ChronoUnit.WEEKS.between(start,WeeklyTechnicalService.monday(b.date()));double c=(up?100+week*1.5:350-week*1.5)+4*Math.sin(week*Math.PI/4);rows.set(i,new HistoricalCandle(b.date(),b.time(),c-.1,c+.5,c-.5,c,1_000_000L));}var r=eval(rows,day);assertThat(r.trend()).isEqualTo(up?"UPTREND":"DOWNTREND");assertThat(r.pivots()).isNotEmpty().allMatch(v->!v.weekStart().isAfter(r.weeks().get(r.weeks().size()-3).weekStart()));}}

}
